<script setup lang="ts">
import { ChevronDown, Heart, Menu, Percent, Search, ShoppingCart, UserRound, X } from '@lucide/vue'
import type { StoreCategory, StorefrontPayload } from '#shared/types/storefront'
import type { StorefrontBranding } from '#shared/types/branding'
import BaseWhatsAppButton from './BaseWhatsAppButton.vue'
import { useStorefrontCommerce } from '~~/layers/storefront-core/app/composables/useStorefrontCommerce'

const props = defineProps<{ storefront: StorefrontPayload, storeName: string, logoUrl?: string | null, categories: StoreCategory[], theme: StorefrontBranding }>()
const menuOpen = ref(false)
const searchOpen = ref(false)
const search = ref('')
const { cart, canPurchase, wishlist, cartOpen, initialize } = useStorefrontCommerce(props.storefront)
const submitSearch = async () => {
  const term = search.value.trim()
  await navigateTo(term ? { path: '/produtos', query: { busca: term } } : '/produtos')
  searchOpen.value = false
}
onMounted(initialize)
</script>

<template>
  <div class="store-header">
    <header class="main-header header-container">
      <button class="mobile-menu" type="button" :aria-expanded="menuOpen" aria-label="Abrir menu" @click="menuOpen=!menuOpen"><X v-if="menuOpen" :size="21"/><Menu v-else :size="21"/></button>
      <NuxtLink to="/" class="brand"><img v-if="logoUrl" :src="logoUrl" :alt="storeName"><template v-else><span class="brand-symbol"></span><span><strong>{{ storeName }}</strong><small>cuidado todos os dias</small></span></template></NuxtLink>
      <form class="desktop-search join" @submit.prevent="submitSearch"><NuxtLink to="/categorias" class="category-select join-item">Categorias <ChevronDown :size="14"/></NuxtLink><label class="sr-only" for="base-search">Buscar produtos</label><input id="base-search" v-model="search" class="input join-item" placeholder="Busque por produtos, marcas ou sintomas"><button type="submit" class="btn btn-primary join-item" aria-label="Buscar"><Search :size="21"/></button></form>
      <div class="header-actions"><BaseWhatsAppButton :phone="theme.whatsapp_phone" variant="header" /><button class="icon-action search-trigger" type="button" aria-label="Buscar" @click="searchOpen=!searchOpen"><Search :size="20"/></button><NuxtLink class="icon-action" to="/conta" aria-label="Minha conta"><UserRound :size="21"/><span>Conta</span></NuxtLink><NuxtLink class="icon-action favorite" to="/favoritos" aria-label="Meus favoritos"><Heart :size="21"/><span>Favoritos</span><b v-if="wishlist.length">{{ wishlist.length }}</b></NuxtLink><button v-if="canPurchase" class="cart" type="button" aria-label="Abrir carrinho" @click="cartOpen=true"><ShoppingCart :size="21"/><span>Carrinho</span><b>{{ cart.totals.items_count }}</b></button></div>
    </header>
    <form v-if="searchOpen" class="mobile-search" @submit.prevent="submitSearch"><Search :size="18"/><input v-model="search" aria-label="Buscar produtos" placeholder="Busque por produtos ou marcas"><button class="btn btn-primary">Buscar</button></form>
    <nav class="category-nav" :class="{open:menuOpen}" aria-label="Navegação principal"><div class="header-container"><NuxtLink class="all-categories" to="/categorias"><Menu :size="17"/>Todas as categorias</NuxtLink><NuxtLink to="/produtos">Produtos</NuxtLink><NuxtLink v-for="category in categories.slice(0,4)" :key="category.id" :to="`/categoria/${category.slug}`">{{ category.name }}</NuxtLink><NuxtLink class="offers" to="/produtos"><Percent :size="16"/>Ofertas</NuxtLink></div></nav>
  </div>
</template>

